/* Robo-LaEle - dicionário do "lá ele".
 *
 * A lista de palavras fica empacotada no bloco PAYLOAD lá embaixo, ofuscada
 * (XOR + base64) só para não virar uma lista legível no repositório. Isto NÃO é
 * criptografia: a chave está neste arquivo e a extensão precisa decodificar
 * tudo em tempo de execução. Para editar, use scripts/dictionary.js
 * (export -> editar o JSON -> build).
 *
 * Formas e stems podem ter acento/caixa alta: o motor normaliza tudo.
 * Cuidado: "dá" e "dê" normalizam para "da"/"de", então ficam de fora. */
var LaEle = globalThis.LaEle = globalThis.LaEle || {};

(function () {
  'use strict';

  var KEY = 'laele-robo-v1';

  // única fonte das faixas de raridade: storage e popup usam esta mesma função
  function tierOf(coef) {
    coef = Number(coef) || 0;
    if (coef < 1.5) return 'leve';
    if (coef < 2.5) return 'comum';
    if (coef < 3.5) return 'pesado';
    return 'lendario';
  }

  function xor(bytes) {
    var out = new Uint8Array(bytes.length);
    for (var i = 0; i < bytes.length; i++) out[i] = bytes[i] ^ KEY.charCodeAt(i % KEY.length);
    return out;
  }

  function toBytes(bin) {
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }

  // lista de entradas -> texto ofuscado
  function encode(list) {
    var bytes = xor(new TextEncoder().encode(JSON.stringify(list)));
    var bin = '';
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }

  // texto ofuscado -> lista de entradas
  function decode(text) {
    return JSON.parse(new TextDecoder('utf-8').decode(xor(toBytes(atob(text)))));
  }

  function build(raw) {
    return raw.map(function (e) {
      var forms = e.forms || [];
      return {
        id: e.id,
        label: e.label,
        coef: e.coef,
        tier: tierOf(e.coef),
        forms: forms,
        stems: e.stems || [],
        phrase: forms.length > 0 && forms.every(function (f) { return /\s/.test(f.trim()); })
      };
    });
  }

  /*PAYLOAD-START*/
  var PAYLOAD = '';
  /*PAYLOAD-END*/

  LaEle.dictionary = {
    version: 1,
    entries: PAYLOAD ? build(decode(PAYLOAD)) : [],
    tierOf: tierOf,
    codec: { encode: encode, decode: decode }
  };
})();

if (typeof module !== 'undefined' && module.exports) module.exports = LaEle.dictionary;
